    public function buscaEmpenhoCancelado($seqempenho){
        $di = $this->dtDataInicial;
        $df = $this->dtDataFinal;

        $sql = pg_query("SELECT * FROM empanulado WHERE e94_numemp = {$seqempenho} AND e94_data between '{$di}' and '{$df}'");
        $resultado = pg_fetch_all($sql);
        return $resultado[0];

    }

    public function buscaCPFordenador($cgm){
        $sql = pg_query("SELECT z01_cgccpf FROM cgm WHERE z01_numcgm = {$cgm}");
        $resultado = pg_fetch_all($sql);
        return $resultado[0]["z01_cgccpf"];
    }

    public function gerarDados(){
        $ugs = $this->pegaCgmOrdenador();
        $ugs = $this->buscaCPFordenador($ugs);

        $campos = [
            'e60_numemp',
            'e60_anousu',
            'e91_anousu',
            'e60_codemp',
            'o58_orgao',
            'o58_unidade',
            'e91_vlremp', 'e91_vlranu', 'e91_vlrliq',
            'e91_vlrliq', 'e91_vlrpag',
            'e94_codanu',
            'e94_data',
            'e94_valor',
            'e94_motivo',
            'e94_empanuladotipo',
            'z01_cgccpf',
        ];

        $empenhosx = DB::table('empresto')
            ->select($campos)
            ->join('empenho.empempenho', 'e60_numemp', 'e91_numemp')
            ->join('empenho.empanulado', 'e94_numemp', 'e60_numemp')
            ->join('configuracoes.db_usuacgm', 'id_usuario', 'e94_usuario')
            ->join('protocolo.cgm', 'z01_numcgm', 'cgmlogin')
            ->join('orcamento.orcdotacao', function ($join) {
                $join->on('e60_anousu', 'o58_anousu')
                    ->on('e60_coddot', 'o58_coddot');
            })
            ->where('e91_anousu', $this->iAnoUsu)
            ->where('e60_instit', $this->instit)
            ->whereBetween('e94_data', [$this->dtDataInicial, $this->dtDataFinal])
            ->get();

        $empenhos = $this->voltaLiquidacaoes();
        //$this->testa($empenhos); die("Confere");
        if(count($empenhos) == 0){
            throw new \Exception(sprintf(
                'Não foi encontrado nenhum registro para o arquivo da Remessa de %s',
                'Restos a Pagar - Inscrição'
            ));
        }

        $obj = new stdClass();
        $obj->RestosPagarCancelamentos = [];
        $ix = 1;
        foreach ($empenhos as $empenho) {
            $dadoscancelados = $this->buscaEmpenhoCancelado($empenho->e60_numemp);            
            

            $vaorRPP = $empenho->e60_vlrliq - $empenho->e60_vlrpag;

            $tipo = $vaorRPP > 0 ? 2 : 1;

            $data = (object)[
                'Identificador' => $ix,
                'CodigoUnidadeGestora' => $this->sCodigoTribunal,
                'Competencia' => $this->competencia,
                'NumeroEmpenho' => $empenho->e60_codemp,
                'AnoEmpenho' => $empenho->e60_anousu,
                'Tipo' => $tipo,
                'NumeroCancelamento' => $dadoscancelados["e94_codanu"],
                'DataCancelamento' => $dadoscancelados["e94_data"],
                'AnoCancelamento' => substr($dadoscancelados["e94_data"], 0, 4),
                'Cpf' => $ugs,
                'Justificativa' => Helper::convertAndLimit($dadoscancelados["e94_motivo"], 255),
                'Valor' => $dadoscancelados["e94_valor"],
                'CodigoOrgao' => $empenho->o58_orgao,
                'CodigoUnidadeOrcamentaria' => $empenho->o58_unidade,
                'Liquidacoes' => null
            ];


            $obj->RestosPagarCancelamentos[] = (object)[
                'RestosPagarCancelamento' => $data
            ];
            $ix++;
        }

        $this->aDados = $obj;
    }
